(function(){
  const LAB_KEY='apex-expedition-lab-v1';
  const HUB_KEY='apex-learning-hub-v1';
  const languages=['html','python','dbms'];
  const labels={html:'HTML',python:'Python',dbms:'DBMS'};
  const challenges={
    html:[
      {id:'html-alt',title:'The invisible image',brief:'This image works visually, but a screen reader cannot describe it. Repair the accessibility bug.',code:'<figure>\n  <img src="summit.jpg">\n  <figcaption>Our final project</figcaption>\n</figure>',hint:'Images that carry meaning need a useful alt attribute.',check:c=>/<img[^>]+alt\s*=\s*["'][^"']+["']/i.test(c)},
      {id:'html-label',title:'The nameless field',brief:'The form field has a visible label, but the two are not programmatically connected.',code:'<form>\n  <label>Email address</label>\n  <input type="email" id="email">\n</form>',hint:'Match the label for value to the input id.',check:c=>/<label[^>]+for\s*=\s*["']email["']/i.test(c)},
      {id:'html-button',title:'The fake button',brief:'A clickable div excludes keyboard users. Replace it with the correct interactive element.',code:'<div class="save" onclick="saveLesson()">Save lesson</div>',hint:'Use the native element designed for an action.',check:c=>/<button[^>]*>\s*Save lesson\s*<\/button>/i.test(c)}
    ],
    python:[
      {id:'py-compare',title:'Assignment or comparison?',brief:'The condition tries to assign instead of compare. Repair the operator.',code:'score = 10\nif score = 10:\n    print("Perfect")',hint:'Equality comparison uses two equals signs.',check:c=>/if\s+score\s*==\s*10\s*:/i.test(c)},
      {id:'py-range',title:'The missing final lap',brief:'The loop should print 1 through 5, but it stops too early.',code:'for number in range(1, 5):\n    print(number)',hint:'The stop value passed to range is excluded.',check:c=>/range\s*\(\s*1\s*,\s*6\s*\)/i.test(c)},
      {id:'py-default',title:'The memory leak between calls',brief:'Every call shares the same default list. Rewrite the function with a safe default.',code:'def add_topic(topic, topics=[]):\n    topics.append(topic)\n    return topics',hint:'Use None as the default, then create a list inside the function.',check:c=>/topics\s*=\s*None/.test(c)&&/if\s+topics\s+is\s+None\s*:/.test(c)}
    ],
    dbms:[
      {id:'db-null',title:'The unknown comparison',brief:'This query never finds rows whose grade is missing. Repair the null predicate.',code:'SELECT StudentId\nFROM Enrollment\nWHERE Grade = NULL;',hint:'Null uses a dedicated IS predicate.',check:c=>/grade\s+is\s+null/i.test(c)},
      {id:'db-join',title:'The accidental Cartesian product',brief:'The query combines every student with every enrollment. Add the relationship condition.',code:'SELECT s.Name, e.CourseId\nFROM Student s\nJOIN Enrollment e;',hint:'Join matching StudentId values in an ON clause.',check:c=>/on\s+(?:s\.studentid\s*=\s*e\.studentid|e\.studentid\s*=\s*s\.studentid)/i.test(c)},
      {id:'db-unique',title:'The duplicate identity',brief:'Email is a required business identifier, but the schema allows duplicates. Enforce the missing rule.',code:'CREATE TABLE Student (\n  StudentId bigint PRIMARY KEY,\n  Email varchar(254) NOT NULL\n);',hint:'Add a UNIQUE constraint to Email.',check:c=>/email\s+varchar\s*\(\s*254\s*\)\s+not\s+null\s+unique/i.test(c)||/unique\s*\(\s*email\s*\)/i.test(c)}
    ]
  };
  let lab={bookmarks:[],notes:{},confidence:{},review:{},activities:[],dailyTargets:{},quiz:{},debugSolved:[],debugLang:'html',debugIndex:0,focusSeconds:900,focusRunning:false,narratorVoice:'',narratorRate:1,narratorStyle:'natural'};
  let knownCompleted=new Set(),focusTimer,narration={key:'',segments:[],index:0,speaking:false,paused:false,token:0};
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const today=()=>new Date().toLocaleDateString('en-CA');
  const topicKey=(lang,index)=>`${lang}:${index}`;
  const parseKey=key=>{const [lang,index]=key.split(':');return{lang,index:Number(index)}};
  const curriculum=()=>window.APEX_CURRICULUM||{};
  function readHub(){try{return JSON.parse(localStorage.getItem(HUB_KEY)||'{}')}catch{return{}}}
  function load(){try{lab={...lab,...JSON.parse(localStorage.getItem(LAB_KEY)||'{}')}}catch{}lab.bookmarks=[...new Set(lab.bookmarks||[])];lab.activities=[...new Set(lab.activities||[])];lab.debugSolved=[...new Set(lab.debugSolved||[])];lab.focusRunning=false}
  function save(){localStorage.setItem(LAB_KEY,JSON.stringify(lab))}
  function completedKeys(){const hub=readHub(),set=new Set();languages.forEach(lang=>(hub.completedTopics?.[lang]||[]).forEach(index=>set.add(topicKey(lang,index))));return set}
  function counts(){const hub=readHub(),topics=languages.reduce((n,lang)=>n+(curriculum()[lang]?.length||0),0),learned=languages.reduce((n,lang)=>n+(hub.completedTopics?.[lang]?.length||0),0),puzzles=languages.reduce((n,lang)=>n+(hub.completedPuzzles?.[lang]?.length||0),0);return{hub,topics,learned,puzzles,debug:lab.debugSolved.length}}
  function baseXP(){const c=counts();return c.learned*25+c.puzzles*100}
  function updateXp(){const xp=document.querySelector('#xp');if(xp)xp.textContent=baseXP()+lab.debugSolved.length*75}
  function currentTopic(){const lang=document.querySelector('[data-learn-language].active')?.dataset.learnLanguage||'html';const index=Number(document.querySelector('[data-topic-index].active')?.dataset.topicIndex||0);return{lang,index,key:topicKey(lang,index)}}
  function openTopic(key){const {lang,index}=parseKey(key);document.querySelector('[data-view="learn"]')?.click();document.querySelector(`[data-learn-language="${lang}"]`)?.click();requestAnimationFrame(()=>document.querySelector(`[data-topic-index="${index}"]`)?.click())}
  function hash(text){let value=0;for(const char of text)value=(value*31+char.charCodeAt(0))>>>0;return value}
  function dailyKey(){const day=today();if(lab.dailyTargets[day])return lab.dailyTargets[day];const done=completedKeys(),all=[];languages.forEach(lang=>(curriculum()[lang]||[]).forEach((_,index)=>{const key=topicKey(lang,index);if(!done.has(key))all.push(key)}));if(!all.length)return null;lab.dailyTargets[day]=all[hash(day)%all.length];save();return lab.dailyTargets[day]}
  function streak(){const dates=new Set(lab.activities);let value=0,date=new Date();if(!dates.has(today()))date.setDate(date.getDate()-1);while(dates.has(date.toLocaleDateString('en-CA'))){value++;date.setDate(date.getDate()-1)}return value}
  function nextIncomplete(lang){const done=completedKeys();return(curriculum()[lang]||[]).findIndex((_,index)=>!done.has(topicKey(lang,index)))}
  function dueKeys(){const now=today();return Object.entries(lab.review||{}).filter(([,item])=>item?.next<=now).map(([key])=>key).filter(key=>{const {lang,index}=parseKey(key);return curriculum()[lang]?.[index]})}
  function recommendation(){const due=dueKeys()[0];if(due)return{key:due,reason:'This lesson is due for spaced review, so recalling it now will strengthen long-term memory.'};const low=Object.entries(lab.confidence||{}).find(([key,value])=>Number(value)===1&&completedKeys().has(key));if(low)return{key:low[0],reason:'You marked this lesson as uncertain. A short review here should remove the biggest weak point.'};const wrong=Object.entries(lab.quiz||{}).sort((a,b)=>(b[1].wrong||0)-(a[1].wrong||0)).find(([,score])=>(score.wrong||0)>(score.correct||0));if(wrong)return{key:wrong[0],reason:'Your knowledge checks show this topic needs another look before you climb higher.'};for(const lang of languages){const index=nextIncomplete(lang);if(index>=0)return{key:topicKey(lang,index),reason:'This is the next uncompleted lesson on your current learning path.'}}return{key:null,reason:'Every lesson is complete. Use the debug lab and puzzle arena to keep your skills sharp.'}}
  function topicFromKey(key){if(!key)return null;const {lang,index}=parseKey(key),topic=curriculum()[lang]?.[index];return topic?{lang,index,key,topic}:null}
  function syncCompletions(){const now=completedKeys();let changed=false;for(const key of now){if(!knownCompleted.has(key)){lab.activities.push(today());lab.activities=[...new Set(lab.activities)];lab.review[key]={next:datePlus(1),interval:1};changed=true}}for(const key of knownCompleted){if(!now.has(key)&&lab.review[key]){delete lab.review[key];changed=true}}knownCompleted=now;if(changed)save();updateXp()}
  function datePlus(days){const date=new Date();date.setDate(date.getDate()+days);return date.toLocaleDateString('en-CA')}
  function formatDate(value){if(!value)return'Not scheduled';return new Date(`${value}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
  function progressFor(lang){const hub=readHub(),total=curriculum()[lang]?.length||0,done=hub.completedTopics?.[lang]?.length||0;return{total,done,percent:total?Math.round(done/total*100):0}}
  function renderJourney(){
    const root=document.querySelector('#journeyDashboard');if(!root)return;syncCompletions();const c=counts(),percent=c.topics?Math.round(c.learned/c.topics*100):0,dayKey=dailyKey(),daily=topicFromKey(dayKey),dailyDone=dayKey&&completedKeys().has(dayKey),coach=topicFromKey(recommendation().key),review=dueKeys().slice(0,4),saved=lab.bookmarks.map(topicFromKey).filter(Boolean).slice(0,4),badges=badgeData(c),focus=clockText(lab.focusSeconds);
    root.innerHTML=`<section class="journey-command"><div class="journey-copy"><h1>Your climb, mapped.</h1><p>Apex studies your progress, confidence, quiz results, and review timing to choose the most useful next step—not merely the next page.</p><div class="journey-actions"><button class="btn btn-primary" data-apex-open="${esc((coach||daily)?.key||'')}">${coach?'Continue recommended lesson':'Open today’s mission'}</button><button class="btn btn-secondary" data-apex-view="debug">Enter debug lab</button></div></div><div class="mastery-dial" style="--mastery:${percent}%"><div class="dial-copy"><strong>${percent}%</strong><span>overall mastery</span></div></div></section>
      <div class="journey-stats"><div class="journey-stat"><strong>${c.learned}/${c.topics}</strong><span>lessons learned</span></div><div class="journey-stat"><strong>${streak()} days</strong><span>learning streak</span></div><div class="journey-stat"><strong>${review.length}</strong><span>reviews due</span></div><div class="journey-stat"><strong>${baseXP()+c.debug*75}</strong><span>total XP</span></div></div>
      <section class="journey-section"><div class="journey-section-head"><div><h2>The three-ridge quest map</h2><p>Each ridge is a complete learning path. Progress remains open—you choose the route.</p></div><span class="privacy-note">Saved privately on this device</span></div><div class="ridge-map">${languages.map(renderRidge).join('')}</div></section>
      <section class="journey-section"><div class="journey-section-head"><div><h2>Today at base camp</h2><p>One meaningful mission and one focused study sprint.</p></div></div><div class="mission-grid"><article class="daily-mission"><div><h3>${dailyDone?'Daily mission complete':daily?esc(daily.topic.title):'All lessons complete'}</h3><p>${dailyDone?'You kept the trail moving. Return tomorrow for a new mission.':daily?`${labels[daily.lang]} · ${esc(daily.topic.summary)}`:'Choose a puzzle or debugging case to keep practicing.'}</p>${daily&&!dailyDone?`<button class="btn btn-primary" data-apex-open="${daily.key}">Start daily mission</button>`:''}</div><div class="mission-mark ${dailyDone?'done':''}" aria-hidden="true">${dailyDone?'✓':'1'}</div></article><article class="focus-sprint"><h3>Focus sprint</h3><p>A distraction-free 15-minute climb. The timer stays on this page.</p><div class="focus-clock" id="focusClock">${focus}</div><div class="journey-actions"><button class="btn btn-primary" data-focus-toggle>${lab.focusRunning?'Pause':'Start focus'}</button><button class="btn btn-secondary" data-focus-reset>Reset</button></div></article></div></section>
      <section class="journey-section"><div class="journey-section-head"><div><h2>Your adaptive coach</h2><p>Recommendations change as you learn, review, and answer knowledge checks.</p></div></div><div class="coach-grid"><article class="coach-panel"><span class="coach-label">Best next move</span><h3>${coach?esc(coach.topic.title):'Practice at the summit'}</h3><p class="coach-reason">${esc(recommendation().reason)}</p>${coach?`<button class="btn btn-primary" data-apex-open="${coach.key}">Open recommendation</button>`:`<button class="btn btn-primary" data-apex-view="debug">Open debug lab</button>`}</article><article class="review-panel"><h3>Memory review queue</h3><p>Completed lessons return at useful intervals.</p><div class="review-list">${review.length?review.map(key=>{const item=topicFromKey(key);return`<div class="review-item"><span><strong>${esc(item.topic.title)}</strong><br><small>${labels[item.lang]} · due now</small></span><button data-apex-open="${key}">Review</button></div>`}).join(''):'<div class="empty-guidance">No reviews are due. Finish a lesson to begin spaced review.</div>'}</div></article></div></section>
      <section class="journey-section"><div class="journey-section-head"><div><h2>Field kit</h2><p>Your saved lessons and earned expedition badges.</p></div></div><div class="coach-grid"><article class="saved-panel"><h3>Bookmarked lessons</h3><div class="saved-list">${saved.length?saved.map(item=>`<div class="saved-item"><span><strong>${esc(item.topic.title)}</strong><br><small>${labels[item.lang]}</small></span><button data-apex-open="${item.key}">Open</button></div>`).join(''):'<div class="empty-guidance">Bookmark a lesson to keep it close.</div>'}</div></article><article class="badge-panel"><h3>Achievement passport</h3><div class="badge-grid">${badges.map(b=>`<div class="badge ${b.earned?'earned':''}"><div class="badge-icon" aria-hidden="true">${b.icon}</div><strong>${esc(b.name)}</strong><span>${esc(b.rule)}</span></div>`).join('')}</div></article></div></section>`;
    updateXp();
  }
  function renderRidge(lang){const p=progressFor(lang),next=nextIncomplete(lang),topic=next>=0?curriculum()[lang][next]:null;return`<article class="ridge ridge-${lang}"><div class="ridge-top"><div><div class="ridge-name">${labels[lang]} ridge</div><div class="ridge-count">${p.done} of ${p.total} lessons</div></div><div class="ridge-percent">${p.percent}%</div></div><div class="ridge-line" style="--progress:${p.percent}%"><span></span></div><span class="ridge-next">${topic?`Next camp: <strong>${esc(topic.title)}</strong>`:'Summit reached. Every lesson is complete.'}</span><button class="btn btn-secondary" data-apex-open="${topicKey(lang,Math.max(next,0))}">${topic?'Continue ridge':'Review from base'}</button></article>`}
  function badgeData(c){const hub=c.hub,notes=Object.values(lab.notes||{}).filter(value=>value.trim()).length;return[
    {icon:'◆',name:'First foothold',rule:'Complete 1 lesson',earned:c.learned>=1},
    {icon:'▲',name:'Trail maker',rule:'Complete 10 lessons',earned:c.learned>=10},
    {icon:'≋',name:'Three ridges',rule:'Learn in every course',earned:languages.every(lang=>(hub.completedTopics?.[lang]?.length||0)>0)},
    {icon:'⌁',name:'Bug hunter',rule:'Repair 3 cases',earned:c.debug>=3},
    {icon:'✦',name:'Field scholar',rule:'Save 5 lesson notes',earned:notes>=5},
    {icon:'●',name:'Apex summit',rule:'Complete all lessons',earned:c.learned===c.topics&&c.topics>0}
  ]}
  function speechText(value){return String(value||'').replace(/<([a-z][\w-]*)>/gi,' $1 element ').replace(/<\/([a-z][\w-]*)>/gi,' end $1 ').replace(/→/g,' determines ').replace(/[{}_*`#]/g,' ').replace(/\s+/g,' ').trim()}
  function narrationParts(lang,index){const topic=curriculum()[lang]?.[index];if(!topic)return[];const parts=[];const add=(title,text,kind,sourceIndex=0)=>{const clean=speechText(text);if(!clean)return;const sentences=clean.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[clean];let chunk='';let first=true;for(const sentence of sentences){if(chunk&&(`${chunk} ${sentence}`).length>260){parts.push({title,text:`${first?`${title}. `:''}${chunk}`.trim(),kind,sourceIndex});first=false;chunk=sentence.trim()}else chunk=`${chunk} ${sentence}`.trim()}if(chunk)parts.push({title,text:`${first?`${title}. `:''}${chunk}`.trim(),kind,sourceIndex})};
    add('Lesson introduction',`${topic.title}. ${topic.description}`,'intro');
    add('Learning objectives',(topic.objectives||topic.points||[]).map((item,i)=>`${i+1}. ${item}`).join('. '),'objectives');
    (topic.sections||[]).forEach((section,i)=>add(section.title,section.body,'section',i));
    if(topic.mistakes?.length)add('Common mistakes',topic.mistakes.join('. '),'mistakes');
    if(topic.task)add('Practice assignment',topic.task,'assignment');
    return parts
  }
  function narratorVoices(){if(!('speechSynthesis'in window))return[];const all=window.speechSynthesis.getVoices();const english=all.filter(voice=>/^en[-_]/i.test(voice.lang));return english.length?english:all}
  function narratorPreset(){return{natural:{label:'Natural',pitch:1,rate:1},woman:{label:'Woman voice',pitch:1.08,rate:1},sweet:{label:'Soft & sweet',pitch:1.18,rate:.9}}[lab.narratorStyle]||{label:'Natural',pitch:1,rate:1}}
  function selectedVoice(){const voices=narratorVoices(),preferred=/zira|samantha|victoria|karen|moira|tessa|veena|susan|hazel|aria|jenny|sonia|female/i;return voices.find(voice=>voice.voiceURI===lab.narratorVoice)||((lab.narratorStyle==='woman'||lab.narratorStyle==='sweet')?voices.find(voice=>preferred.test(voice.name)):null)||voices.find(voice=>voice.default)||voices[0]||null}
  function installNarrator(){const card=document.querySelector('#lessonCard'),top=card?.querySelector('.lesson-top');if(!top)return;const current=currentTopic(),existing=card.querySelector('.lesson-narrator');if(existing?.dataset.topic===current.key)return;if(narration.key&&narration.key!==current.key)stopNarration(true);existing?.remove();const panel=document.createElement('section');panel.className='lesson-narrator';panel.dataset.topic=current.key;panel.setAttribute('aria-label','Listen to this lesson');top.after(panel);renderNarrator(panel)}
  function renderNarrator(panel=document.querySelector('.lesson-narrator')){
    if(!panel)return;
    const supported='speechSynthesis'in window&&'SpeechSynthesisUtterance'in window,voices=narratorVoices(),voice=selectedVoice(),preset=narratorPreset(),active=narration.speaking&&narration.key===panel.dataset.topic,progress=active&&narration.segments.length?Math.round((narration.index+1)/narration.segments.length*100):0;
    panel.classList.toggle('is-speaking',active);panel.classList.toggle('is-paused',active&&narration.paused);
    panel.innerHTML=`<div class="narrator-signal" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div><div class="narrator-main"><div class="narrator-title"><strong>Listen to this lesson</strong><span id="narratorStatus" aria-live="polite">${supported?(active?`Part ${narration.index+1} of ${narration.segments.length}: ${esc(narration.segments[narration.index]?.title||'Lesson')}`:`${preset.label}. Apex matches the closest voice available on this device.`):'Voice playback is not supported in this browser.'}</span></div><div class="narrator-progress" aria-hidden="true"><span style="width:${progress}%"></span></div></div><div class="narrator-controls"><button class="narrator-play" data-narrator-toggle ${supported?'':'disabled'}>${active?(narration.paused?'Resume':'Pause'):'Listen'}</button><button class="narrator-stop" data-narrator-stop ${active?'':'disabled'}>Stop</button><label>Style<select data-narrator-style ${supported?'':'disabled'}><option value="natural" ${lab.narratorStyle==='natural'?'selected':''}>Natural</option><option value="woman" ${lab.narratorStyle==='woman'?'selected':''}>Woman voice</option><option value="sweet" ${lab.narratorStyle==='sweet'?'selected':''}>Soft & sweet</option></select></label><label>Voice<select data-narrator-voice ${supported?'':'disabled'}><option value="">${voices.length?'Auto-match':'Default device voice'}</option>${voices.map(item=>`<option value="${esc(item.voiceURI)}" ${lab.narratorVoice&&voice?.voiceURI===item.voiceURI?'selected':''}>${esc(item.name)} (${esc(item.lang)})</option>`).join('')}</select></label><label>Speed<select data-narrator-rate ${supported?'':'disabled'}>${[.75,1,1.25,1.5].map(rate=>`<option value="${rate}" ${Number(lab.narratorRate)===rate?'selected':''}>${rate}×</option>`).join('')}</select></label></div>`
  }
  function clearNarrationHighlight(){document.querySelectorAll('.narrating-now').forEach(node=>node.classList.remove('narrating-now'))}
  function highlightNarration(segment){clearNarrationHighlight();let target;if(segment.kind==='intro')target=document.querySelector('#lessonCard .lesson-top');else if(segment.kind==='objectives')target=document.querySelector('#lessonCard .lesson-section');else if(segment.kind==='section')target=document.querySelectorAll('#lessonCard .deep-section')[segment.sourceIndex];else if(segment.kind==='mistakes')target=document.querySelector('#lessonCard .mistake-list');else if(segment.kind==='assignment')target=document.querySelector('#lessonCard .mini-task');target?.classList.add('narrating-now')}
  function startNarration(){if(!('speechSynthesis'in window))return;const current=currentTopic();if(narration.speaking&&narration.key===current.key){if(narration.paused){window.speechSynthesis.resume();narration.paused=false}else{window.speechSynthesis.pause();narration.paused=true}renderNarrator();return}stopNarration(true);narration={key:current.key,segments:narrationParts(current.lang,current.index),index:0,speaking:true,paused:false,token:narration.token+1};speakNarrationPart()}
  function speakNarrationPart(){if(!narration.speaking)return;if(narration.index>=narration.segments.length){finishNarration();return}const segment=narration.segments[narration.index],token=narration.token,utterance=new SpeechSynthesisUtterance(segment.text),voice=selectedVoice(),preset=narratorPreset();if(voice)utterance.voice=voice;utterance.lang=voice?.lang||'en-US';utterance.rate=(Number(lab.narratorRate)||1)*preset.rate;utterance.pitch=preset.pitch;utterance.onstart=()=>{if(token!==narration.token)return;highlightNarration(segment);renderNarrator()};utterance.onend=()=>{if(token!==narration.token||!narration.speaking)return;narration.index++;narration.paused=false;speakNarrationPart()};utterance.onerror=error=>{if(token!==narration.token||['canceled','interrupted'].includes(error.error))return;finishNarration('Voice playback stopped. Choose another device voice and try again.')};window.speechSynthesis.speak(utterance);renderNarrator()}
  function stopNarration(silent=false){if('speechSynthesis'in window)window.speechSynthesis.cancel();narration.token++;narration.speaking=false;narration.paused=false;narration.index=0;clearNarrationHighlight();if(!silent)renderNarrator()}
  function finishNarration(message='Lesson narration complete.'){narration.speaking=false;narration.paused=false;clearNarrationHighlight();renderNarrator();const status=document.querySelector('#narratorStatus');if(status)status.textContent=message}
  function restartNarrationPart(){if(!narration.speaking)return;const index=narration.index,key=narration.key,segments=narration.segments;window.speechSynthesis.cancel();narration={key,segments,index,speaking:true,paused:false,token:narration.token+1};speakNarrationPart()}
  function renderLessonTools(){const host=document.querySelector('#apexLessonTools');if(!host||host.dataset.ready)return;const {lang,index,key}=currentTopic(),bookmarked=lab.bookmarks.includes(key),confidence=Number(lab.confidence[key]||0),review=lab.review[key];host.dataset.ready='true';host.innerHTML=`<section class="lesson-companion" aria-label="Personal learning tools"><div class="companion-card"><h3>Remember this lesson</h3><p>Bookmark it, rate your confidence, and let Apex choose better recommendations.</p><button class="bookmark-btn ${bookmarked?'saved':''}" data-bookmark="${key}">${bookmarked?'★ Bookmarked':'☆ Bookmark lesson'}</button><h3 style="margin-top:16px">How confident are you?</h3><div class="confidence-row">${[['1','Not yet'],['2','Getting it'],['3','Confident']].map(([value,label])=>`<button class="confidence-btn ${confidence===Number(value)?'active':''}" data-confidence="${value}" data-key="${key}">${label}</button>`).join('')}</div>${review?`<p style="margin:13px 0 0">Next review: <strong>${formatDate(review.next)}</strong></p>${review.next<=today()?`<button class="bookmark-btn" style="margin-top:8px" data-reviewed="${key}">I reviewed this today</button>`:''}`:''}</div><div class="companion-card"><h3>Private field notes</h3><p>Write the idea in your own words. Notes stay only in this browser.</p><textarea class="lesson-note" data-note="${key}" placeholder="What did you learn? What still feels difficult?">${esc(lab.notes[key]||'')}</textarea><span class="note-status">Saved automatically on this device</span></div></section>`}
  function renderDebug(){const root=document.querySelector('#debugLab');if(!root)return;const lang=lab.debugLang||'html',items=challenges[lang],index=Math.min(lab.debugIndex||0,items.length-1),item=items[index],solved=lab.debugSolved.includes(item.id);root.innerHTML=`<div class="debug-head"><div><h1>Debugging detective lab</h1><p>Real developers spend more time understanding broken code than typing perfect code. Diagnose each case, repair it, and test the result safely.</p></div><div class="debug-score"><strong>${lab.debugSolved.length}/${Object.values(challenges).flat().length}</strong><span>cases solved · ${lab.debugSolved.length*75} lab XP</span></div></div><div class="debug-tabs">${languages.map(value=>`<button class="debug-tab ${value===lang?'active':''}" data-debug-lang="${value}">${labels[value]}</button>`).join('')}</div><div class="debug-layout"><aside class="case-file"><h2>Case files</h2><div class="case-list">${items.map((caseItem,i)=>`<button class="case-btn ${i===index?'active':''} ${lab.debugSolved.includes(caseItem.id)?'solved':''}" data-debug-index="${i}">${esc(caseItem.title)}</button>`).join('')}</div></aside><article class="debug-case"><header class="case-brief"><h2>${esc(item.title)}</h2><p>${esc(item.brief)}</p></header><div class="case-workbench"><textarea class="bug-editor" id="bugEditor" spellcheck="false" aria-label="Repair the broken code">${esc(item.code)}</textarea><div class="actions"><button class="btn btn-primary" data-debug-check>Test repair</button><button class="btn btn-secondary" data-debug-hint>Show a clue</button><button class="btn btn-secondary" data-debug-reset>Reset case</button></div><div class="debug-hint" id="debugHint">${esc(item.hint)}</div><div id="debugFeedback" aria-live="polite">${solved?'<div class="debug-feedback win">Solved before. Try repairing it again from memory.</div>':''}</div></div></article></div>`;updateXp()}
  function checkDebug(){const lang=lab.debugLang,index=lab.debugIndex||0,item=challenges[lang][index],code=document.querySelector('#bugEditor')?.value||'',feedback=document.querySelector('#debugFeedback');if(item.check(code)){const first=!lab.debugSolved.includes(item.id);if(first){lab.debugSolved.push(item.id);lab.activities.push(today());lab.activities=[...new Set(lab.activities)];save()}feedback.innerHTML=`<div class="debug-feedback win"><strong>Case closed.</strong> ${first?'+75 lab XP earned.':'Your repair still passes.'}</div>`;updateXp();setTimeout(renderDebug,900)}else feedback.innerHTML='<div class="debug-feedback try"><strong>The bug is still active.</strong> Compare the goal with the exact syntax and try one smaller change.</div>'}
  function clockText(seconds){return`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
  function toggleFocus(){lab.focusRunning=!lab.focusRunning;save();renderJourney();startTimer()}
  function resetFocus(){lab.focusRunning=false;lab.focusSeconds=900;save();renderJourney()}
  function startTimer(){clearInterval(focusTimer);if(!lab.focusRunning)return;focusTimer=setInterval(()=>{if(!lab.focusRunning)return;if(lab.focusSeconds>0)lab.focusSeconds--;const clock=document.querySelector('#focusClock');if(clock)clock.textContent=clockText(lab.focusSeconds);if(lab.focusSeconds<=0){lab.focusRunning=false;lab.focusSeconds=900;lab.activities.push(today());lab.activities=[...new Set(lab.activities)];save();clearInterval(focusTimer);document.querySelector('#toast')?.classList.add('visible');const toast=document.querySelector('#toast');if(toast){toast.textContent='Focus sprint complete';setTimeout(()=>toast.classList.remove('visible'),1800)}renderJourney()}if(lab.focusSeconds%15===0)save()},1000)}
  function handleClick(e){
    if(e.target.closest('.brand')){e.preventDefault();document.querySelector('[data-view="journey"]')?.click();return}
    if(e.target.closest('[data-narrator-toggle]')){startNarration();return}
    if(e.target.closest('[data-narrator-stop]')){stopNarration();return}
    const navigation=e.target.closest('[data-view]');if(navigation&&navigation.dataset.view!=='learn')stopNarration(true);
    const open=e.target.closest('[data-apex-open]');if(open&&open.dataset.apexOpen){openTopic(open.dataset.apexOpen);return}
    const view=e.target.closest('[data-apex-view]');if(view){document.querySelector(`[data-view="${view.dataset.apexView}"]`)?.click();return}
    const bookmark=e.target.closest('[data-bookmark]');if(bookmark){const key=bookmark.dataset.bookmark;lab.bookmarks=lab.bookmarks.includes(key)?lab.bookmarks.filter(item=>item!==key):[...lab.bookmarks,key];save();document.querySelector('#apexLessonTools')?.removeAttribute('data-ready');renderLessonTools();return}
    const confidence=e.target.closest('[data-confidence]');if(confidence){lab.confidence[confidence.dataset.key]=Number(confidence.dataset.confidence);save();document.querySelector('#apexLessonTools')?.removeAttribute('data-ready');renderLessonTools();return}
    const reviewed=e.target.closest('[data-reviewed]');if(reviewed){const item=lab.review[reviewed.dataset.reviewed]||{interval:1};item.interval=Math.min((item.interval||1)*2,30);item.next=datePlus(item.interval);lab.review[reviewed.dataset.reviewed]=item;save();document.querySelector('#apexLessonTools')?.removeAttribute('data-ready');renderLessonTools();return}
    if(e.target.closest('[data-focus-toggle]')){toggleFocus();return}if(e.target.closest('[data-focus-reset]')){resetFocus();return}
    const debugLang=e.target.closest('[data-debug-lang]');if(debugLang){lab.debugLang=debugLang.dataset.debugLang;lab.debugIndex=0;save();renderDebug();return}
    const debugIndex=e.target.closest('[data-debug-index]');if(debugIndex){lab.debugIndex=Number(debugIndex.dataset.debugIndex);save();renderDebug();return}
    if(e.target.closest('[data-debug-check]')){checkDebug();return}if(e.target.closest('[data-debug-hint]')){document.querySelector('#debugHint')?.classList.toggle('visible');return}if(e.target.closest('[data-debug-reset]')){renderDebug();return}
    if(e.target.closest('[data-quiz-option]'))setTimeout(()=>recordQuizFromTarget(e.target),0);
    if(e.target.closest('#runBtn'))setTimeout(updateXp,0);
    if(e.target.closest('[data-view="journey"]'))setTimeout(renderJourney,0);if(e.target.closest('[data-view="debug"]'))setTimeout(renderDebug,0)
  }
  function recordQuizFromTarget(target){const option=target.closest('[data-quiz-option]');if(!option)return;const quiz=option.closest('.quiz'),correct=Number(option.dataset.quizOption)===Number(quiz?.dataset.quizAnswer),{key}=currentTopic(),score=lab.quiz[key]||{correct:0,wrong:0};score[correct?'correct':'wrong']++;lab.quiz[key]=score;if(!correct&&!lab.confidence[key])lab.confidence[key]=1;save()}
  function handleInput(e){const note=e.target.closest('[data-note]');if(!note)return;lab.notes[note.dataset.note]=note.value;save()}
  function handleChange(e){const style=e.target.closest('[data-narrator-style]');if(style){lab.narratorStyle=style.value;lab.narratorVoice='';save();if(narration.speaking)restartNarrationPart();else renderNarrator();return}const voice=e.target.closest('[data-narrator-voice]');if(voice){lab.narratorVoice=voice.value;save();if(narration.speaking)restartNarrationPart();else renderNarrator();return}const rate=e.target.closest('[data-narrator-rate]');if(rate){lab.narratorRate=Number(rate.value);save();if(narration.speaking)restartNarrationPart();else renderNarrator()}}
  function installLessonTools(){installNarrator();let host=document.querySelector('#apexLessonTools');if(!host){const actions=document.querySelector('#lessonCard .lesson-actions');if(!actions)return;host=document.createElement('div');host.id='apexLessonTools';actions.before(host)}renderLessonTools()}
  function init(){load();knownCompleted=completedKeys();document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);window.addEventListener('beforeunload',()=>stopNarration(true));if('speechSynthesis'in window&&window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',()=>renderNarrator());const lesson=document.querySelector('#lessonCard');if(lesson)new MutationObserver(()=>{syncCompletions();installLessonTools()}).observe(lesson,{childList:true,subtree:false});requestAnimationFrame(()=>{syncCompletions();installLessonTools();if(document.querySelector('#journeyView.active'))renderJourney();if(document.querySelector('#debugView.active'))renderDebug();startTimer()})}
  window.ApexLab={renderJourney,renderDebug,renderLessonTools,startNarration,stopNarration};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
